function ModelFields({title,value,onChange,disabled,connections=[]}:{title:string;value:Model;onChange:(v:Model)=>void;disabled:boolean;connections?:Connection[]}){return <fieldset disabled={disabled} className="min-w-0 space-y-2 rounded-md border p-3"><legend className="px-1 text-sm font-semibold">{title}</legend><Select aria-label={title+' — провайдер'} value={value.provider} onChange={e=>onChange({provider:e.target.value as Model['provider'],model:value.model})}><option value="anthropic">Anthropic напрямую</option><option value="anymodel">AnyModel</option><option value="gemini">Gemini напрямую</option><option value="compatible">Совместимое подключение</option></Select>{value.provider==='compatible'&&<Select aria-label={title+' — подключение'} value={value.connectionId??''} onChange={e=>{const c=connections.find(c=>c.id===e.target.value);onChange({...value,connectionId:c?.id,connectionHash:c?.hash});}}><option value="">Выберите подключение</option>{connections.map(c=><option value={c.id} key={c.id}>{c.name}</option>)}</Select>}<Input aria-label={title+' — точный model ID'} value={value.model} maxLength={180} onChange={e=>onChange({...value,model:e.target.value})} placeholder="Точный model ID из вашего подключения"/></fieldset>;}

