 async function local<T>(path:string,json?:unknown){abort.current?.abort();const c=new AbortController();abort.current=c;const e=++epoch.current;try{const r=await api<T>(path,{signal:c.signal,...(json===undefined?{}:{method:'POST',json})});if(alive.current&&!c.signal.aborted&&e===epoch.current)return r;}finally{if(abort.current===c)abort.current=null;}}
